package org.apache.commons.codec.binary;

import java.io.*;
import java.math.*;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for the Base64 constructor and related functionality.
 * Focuses on maximizing coverage for the default constructor.
 */
public class Base64_Base64_TriageGen0Test {

    @Test
    public void testDefaultConstructor() {
        // Tests the public Base64() constructor
        // This constructor calls this(false), so we verify the default state
        Base64 base64 = new Base64();
        assertFalse("Default constructor should not be URL safe", base64.isUrlSafe());
    }

    @Test
    public void testUrlSafeConstructor() {
        // Tests the public Base64(boolean urlSafe) constructor
        Base64 urlSafeBase64 = new Base64(true);
        assertTrue("Constructor with true should be URL safe", urlSafeBase64.isUrlSafe());

        Base64 nonUrlSafeBase64 = new Base64(false);
        assertFalse("Constructor with false should not be URL safe", nonUrlSafeBase64.isUrlSafe());
    }

    @Test
    public void testLineLengthConstructor() {
        // Tests the public Base64(int lineLength) constructor
        int lineLength = 64;
        Base64 base64 = new Base64(lineLength);
        // Since we can't access lineLength field directly via getter in the provided signature,
        // we verify it doesn't throw an exception and maintains default URL safety.
        assertFalse(base64.isUrlSafe());
    }

    @Test
    public void testLineLengthAndSeparatorConstructor() {
        // Tests the public Base64(int lineLength, byte[] lineSeparator) constructor
        int lineLength = 76;
        byte[] lineSeparator = "\r\n".getBytes();
        Base64 base64 = new Base64(lineLength, lineSeparator);
        assertFalse(base64.isUrlSafe());
    }

    @Test
    public void testAllArgsConstructor() {
        // Tests the public Base64(int lineLength, byte[] lineSeparator, boolean urlSafe) constructor
        int lineLength = 44;
        byte[] lineSeparator = "-".getBytes();
        boolean urlSafe = true;
        Base64 base64 = new Base64(lineLength, lineSeparator, urlSafe);
        assertTrue(base64.isUrlSafe());
    }

    @Test
    public void testStaticIsBase64() {
        // Testing the static method isBase64 to ensure class integrity
        // 'A' is 65 in ASCII, which is a valid Base64 character
        assertTrue(Base64.isBase64((byte) 'A'));
        // '!' is 33 in ASCII, which is not a valid Base64 character
        assertFalse(Base64.isBase64((byte) '!'));
    }

    @Test
    public void testStaticIsArrayByteBase64() {
        // Testing the static method isArrayByteBase64
        byte[] valid = {'A', 'B', 'C', 'D'};
        byte[] invalid = {'A', '!', 'C', 'D'};
        assertTrue(Base64.isArrayByteBase64(valid));
        assertFalse(Base64.isArrayByteBase64(invalid));
    }
}
